style.css:
@-moz-document domain("roblox.com") {
/* Target the main 'Play' button on the game page */
    .btn-common-play-game-lg, 
    .btn-primary-md {
        /* Baby Green color (a light, soft green) */
        background-color: #98fb98 !important; 
        
        /* Optional: Change the border to match */
        border-color: #79d879 !important;
        
        /* Optional: Change the text color for better contrast if needed */
        color: #1f1f1f !important;
    }

    /* Target the hover state to keep the baby green look when mousing over */
    .btn-common-play-game-lg:hover, 
    .btn-primary-md:hover {
        background-color: #6edc6e !important; /* A slightly darker green for feedback */
        border-color: #55b655 !important;
    }
}
